query:
PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:iceOriginType nltl:seaIceOrigin ;
           nltl:winterGrowthCount ?growthCount ;
           nltl:iceThickness ?thicknessNode .

    ?thicknessNode qudt:numericValue ?thickness ;
                    qudt:unit <http://qudt.org/vocab/unit/M> .

    FILTER (
        datatype(?growthCount) = xsd:integer &&
        ?growthCount <= 1 &&
        datatype(?thickness) = xsd:decimal &&
        ?thickness >= 0.3 &&
        ?thickness <= 2.0
    )

    FILTER NOT EXISTS {
        $this nltl:iceTypeClassification nltl:firstYearIce .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:iceOriginType nltl:seaIceOrigin ;
           nltl:winterGrowthCount ?growth ;
           nltl:iceThickness ?thicknessNode .

    ?thicknessNode qudt:numericValue ?thickness ;
                    qudt:unit unit:M .

    FILTER (
        ?growth <= 1 &&
        ?thickness >= 0.3 &&
        ?thickness <= 2.0
    )

    FILTER NOT EXISTS {
        $this nltl:iceTypeClassification nltl:firstYearIce .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:iceCondition ?condition .
    FILTER (STR(?condition) = "bergy waters")
    FILTER NOT EXISTS {
        $this nltl:landOriginIceConcentration ?landConcentration .
        ?landConcentration a qudt:QuantityValue ;
            qudt:numericValue ?landValue ;
            qudt:unit unit:UNITLESS .
        FILTER (datatype(?landValue) = xsd:decimal)
        FILTER (?landValue < 1)

        $this nltl:totalIceConcentration ?totalConcentration .
        ?totalConcentration a qudt:QuantityValue ;
            qudt:numericValue ?totalValue ;
            qudt:unit unit:UNITLESS .
        FILTER (datatype(?totalValue) = xsd:decimal)
        FILTER (?totalValue <= 1)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>

SELECT $this
WHERE {
    $this nltl:openingActuationType ?actuationType .
    FILTER (STR(?actuationType) = "hydraulic")
    FILTER NOT EXISTS {
        $this nltl:hydraulicFluidFreezingOrViscosityControlPresent ?controlPresent .
        FILTER (?controlPresent = true)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this a nltl:ship ;
          nltl:exposedMachineryOrFoundationMaterial ?material .
    FILTER NOT EXISTS {
        $this nltl:approvingAuthority ?authority ;
              nltl:approvalStandard ?standard ;
              nltl:materialApprovalStatus nltl:evidenceStateApproved ;
              nltl:polarServiceTemperature ?temperature .
        FILTER (
            ?authority IN (
                "Administration"^^xsd:string,
                "recognized organization accepted by the Administration"^^xsd:string
            )
        )
        FILTER (
            ?standard IN (
                "standard acceptable to the Organization"^^xsd:string,
                "another standard offering an equivalent level of safety"^^xsd:string
            )
        )
        ?temperature qudt:numericValue ?numericValue ;
                     qudt:unit unit:DEG_C .
        FILTER (datatype(?numericValue) = xsd:decimal)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:hasComponent ?pump .
    ?pump a ?pumpType .
    FILTER (
        ?pumpType IN (
            nltl:firePump,
            nltl:emergencyFirePump,
            nltl:waterMistPump,
            nltl:waterSprayPump
        )
    )
    FILTER NOT EXISTS {
        ?pump nltl:hasContainingCompartment ?compartment .
        ?compartment nltl:maintainedTemperature ?temperature .
        ?temperature a qudt:QuantityValue ;
            qudt:numericValue ?value ;
            qudt:unit unit:DEG_C .
        FILTER (
            DATATYPE(?value) = xsd:decimal &&
            xsd:decimal(?value) > 0
        )
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:addedLifeSavingDeviceRequiresPower ?requiresPower .
    FILTER (?requiresPower = true)
    FILTER NOT EXISTS {
        $this nltl:devicePowerSourceIndependentOfMainPower ?independent .
        FILTER (?independent = true)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:personalOrGroupSurvivalEquipmentRequired true ;
          nltl:personsOnBoard ?persons ;
          nltl:availableSurvivalEquipmentCapacity ?capacity .
    FILTER (?capacity < CEIL(xsd:decimal(?persons) * 1.10))
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX sh: <http://www.w3.org/ns/shacl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:bridgeConfigurationType
        nltl:asternViewRequiredBridgeConfiguration .
    FILTER NOT EXISTS {
        $this nltl:clearViewAsternStatus ?status .
        FILTER (
            datatype(?status) = xsd:boolean &&
            ?status = true
        )
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:bridgeConfigurationType
        nltl:asternViewRequiredBridgeConfiguration .
    FILTER NOT EXISTS {
        $this nltl:clearViewAsternStatus ?status .
        FILTER (
            datatype(?status) = xsd:boolean &&
            ?status = true
        )
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
SELECT $this
WHERE {
    $this nltl:requiredSensorProjectsBelowHull true .
    FILTER NOT EXISTS {
        $this nltl:sensorIceProtectionPresent true .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
SELECT $this
WHERE {
    $this nltl:hasNonMagneticHeadingMeans ?means .
    FILTER NOT EXISTS {
        ?means nltl:independentFromHeadingMeans ?otherMeans .
        FILTER (?otherMeans != ?means)
        $this nltl:hasNonMagneticHeadingMeans ?otherMeans .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:hasNonMagneticHeadingMeans ?means .
    FILTER NOT EXISTS {
        ?means nltl:independentFromHeadingMeans ?otherMeans .
        FILTER (?otherMeans != ?means)
        $this nltl:hasNonMagneticHeadingMeans ?otherMeans .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:plannedOrActualLatitude ?latitudeNode .
    ?latitudeNode qudt:numericValue ?latitude .
    FILTER (?latitude > "80"^^xsd:decimal)
    FILTER (
        NOT EXISTS {
            $this nltl:gnssCompassOrEquivalentCount ?count .
            FILTER (?count >= 1)
        }
        ||
        NOT EXISTS {
            $this nltl:connectedToMainPower ?mainPower .
        }
        ||
        NOT EXISTS {
            $this nltl:connectedToEmergencyPower ?emergencyPower .
        }
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:shipCategory ?category ;
          nltl:shipType ?shipType ;
          nltl:constructionDate ?constructionDate ;
          nltl:cargoTankCarriesOil ?carriesOil .

    FILTER (
        ?category IN (
            nltl:polarShipCategoryA,
            nltl:polarShipCategoryB
        )
    )
    FILTER (?constructionDate >= "2017-01-01"^^xsd:date)
    FILTER (?carriesOil = true)
    FILTER NOT EXISTS {
        $this a nltl:oilTanker .
    }

    FILTER NOT EXISTS {
        $this nltl:cargoTankOuterShellSeparation ?separation .
        ?separation qudt:numericValue ?value ;
                    qudt:unit unit:M .
        FILTER (datatype(?value) = xsd:decimal)
        FILTER (?value >= "0.76"^^xsd:decimal)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:shipCategory ?category ;
          nltl:shipType ?shipType ;
          nltl:constructionDate ?constructionDate ;
          nltl:cargoTankCarriesOil ?carriesOil .

    FILTER (?category IN (
        nltl:polarShipCategoryA,
        nltl:polarShipCategoryB
    ))
    FILTER (?shipType != "oil_tanker")
    FILTER (?constructionDate >= "2017-01-01"^^xsd:date)
    FILTER (?carriesOil = true)
    FILTER NOT EXISTS {
        $this rdf:type nltl:oilTanker
    }

    FILTER NOT EXISTS {
        $this nltl:cargoTankOuterShellSeparation ?separation .
        ?separation qudt:numericValue ?value ;
                    qudt:unit unit:M .
        FILTER (datatype(?value) = xsd:decimal)
        FILTER (?value >= "0.76"^^xsd:decimal)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:shipCategory ?category .
    FILTER (?category IN (
        nltl:polarShipCategoryA,
        nltl:polarShipCategoryB
    )) .

    $this nltl:iceConcentration ?iceQuantity .
    ?iceQuantity qudt:numericValue ?iceValue ;
                  qudt:unit unit:UNITLESS .
    FILTER (?iceValue > 1) .

    $this nltl:extendedPeriodOperation true ;
          nltl:sewageDischargeOccurs true .

    FILTER NOT EXISTS {
        $this nltl:approvedSewageTreatmentPlantUsed true ;
              nltl:administrationDischargeApprovalStatus nltl:evidenceStateApproved .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:shipCategory ?category .
    FILTER (?category IN (
        nltl:polarShipCategoryA,
        nltl:polarShipCategoryB
    ))

    $this nltl:iceConcentration ?ice .
    ?ice qudt:numericValue ?iceValue ;
         qudt:unit unit:UNITLESS .
    FILTER (?iceValue > 1)

    $this nltl:extendedPeriodOperation true .
    $this nltl:sewageDischargeOccurs true .

    FILTER (
        NOT EXISTS {
            $this nltl:approvedSewageTreatmentPlantUsed true
        }
        ||
        NOT EXISTS {
            $this nltl:administrationDischargeApprovalStatus
                  nltl:evidenceStateApproved
        }
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
SELECT $this
WHERE {
    FILTER NOT EXISTS {
        ?ship nltl:hasNonMagneticHeadingMeans $this .
        $this nltl:independentFromHeadingMeans ?other .
        FILTER (?other != $this)
        ?ship nltl:hasNonMagneticHeadingMeans ?other .
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>

SELECT $this
WHERE {
    $this nltl:plannedOrActualLatitude ?latitudeQuantity .
    ?latitudeQuantity qudt:numericValue ?latitude ;
        qudt:unit unit:DEG .
    FILTER (?latitude > 80)
    FILTER (
        NOT EXISTS {
            $this nltl:gnssCompassOrEquivalentCount ?compassCount .
            FILTER (?compassCount >= 1)
        }
        ||
        NOT EXISTS {
            $this nltl:connectedToMainPower ?mainPowerConnection .
        }
        ||
        NOT EXISTS {
            $this nltl:connectedToEmergencyPower ?emergencyPowerConnection .
        }
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:navigatingInIce true ;
          nltl:operatingDraught ?operatingDraught ;
          nltl:upperIceWaterlineDraught ?upperDraught ;
          nltl:operatingTrim ?operatingTrim ;
          nltl:maximumPermittedIceTrim ?maximumTrim .

    ?operatingDraught qudt:numericValue ?operatingDraughtValue ;
                      qudt:unit unit:M .
    ?upperDraught qudt:numericValue ?upperDraughtValue ;
                  qudt:unit unit:M .
    ?operatingTrim qudt:numericValue ?operatingTrimValue ;
                   qudt:unit unit:M .
    ?maximumTrim qudt:numericValue ?maximumTrimValue ;
                 qudt:unit unit:M .

    FILTER (
        datatype(?operatingDraughtValue) = xsd:decimal &&
        datatype(?upperDraughtValue) = xsd:decimal &&
        datatype(?operatingTrimValue) = xsd:decimal &&
        datatype(?maximumTrimValue) = xsd:decimal &&
        (
            ?operatingDraughtValue > ?upperDraughtValue ||
            ?operatingTrimValue > ?maximumTrimValue
        )
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:navigatingInIce true ;
          nltl:operatingDraught ?draught ;
          nltl:upperIceWaterlineDraught ?waterline ;
          nltl:operatingTrim ?trim ;
          nltl:maximumPermittedIceTrim ?maximumTrim .
    ?draught qudt:numericValue ?draughtValue ;
             qudt:unit unit:M .
    ?waterline qudt:numericValue ?waterlineValue ;
               qudt:unit unit:M .
    ?trim qudt:numericValue ?trimValue ;
          qudt:unit unit:M .
    ?maximumTrim qudt:numericValue ?maximumTrimValue ;
                 qudt:unit unit:M .
    FILTER (?draughtValue > ?waterlineValue || ?trimValue > ?maximumTrimValue)
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:intendedRouteSeaWaterSalinity ?intended ;
          nltl:loadingCalculationSeaWaterSalinity ?loading .
    ?intended qudt:numericValue ?intendedValue ;
              qudt:unit nltl:gramPerKilogramSalinityUnit .
    ?loading qudt:numericValue ?loadingValue ;
             qudt:unit nltl:gramPerKilogramSalinityUnit .
    FILTER (
        datatype(?intendedValue) = xsd:decimal &&
        datatype(?loadingValue) = xsd:decimal &&
        ?intendedValue != ?loadingValue
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    $this nltl:intendedRouteSeaWaterSalinity ?intended ;
          nltl:loadingCalculationSeaWaterSalinity ?loading .
    ?intended qudt:numericValue ?intendedValue ;
              qudt:unit nltl:gramPerKilogramSalinityUnit .
    ?loading qudt:numericValue ?loadingValue ;
             qudt:unit nltl:gramPerKilogramSalinityUnit .
    FILTER (?intendedValue != ?loadingValue)
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:iceClass ?ice .
    FILTER (
        ?ice IN (
            nltl:iceClassIa,
            nltl:iceClassIaSuper
        )
    )

    {
        FILTER NOT EXISTS {
            $this nltl:constructionStageDate ?constructionDate .
            FILTER (datatype(?constructionDate) = xsd:date)
        }
    }
    UNION
    {
        $this nltl:constructionStageDate ?constructionDate .
        FILTER (datatype(?constructionDate) != xsd:date)
    }
    UNION
    {
        FILTER NOT EXISTS {
            $this nltl:deliveryDate ?deliveryDate .
            FILTER (datatype(?deliveryDate) = xsd:date)
        }
    }
    UNION
    {
        $this nltl:deliveryDate ?deliveryDate .
        FILTER (datatype(?deliveryDate) != xsd:date)
    }
    UNION
    {
        FILTER NOT EXISTS {
            $this nltl:assessmentDate ?assessmentDate .
            FILTER (datatype(?assessmentDate) = xsd:date)
        }
    }
    UNION
    {
        $this nltl:assessmentDate ?assessmentDate .
        FILTER (datatype(?assessmentDate) != xsd:date)
    }
    UNION
    {
        $this nltl:constructionStageDate ?constructionDate .
        $this nltl:deliveryDate ?deliveryDate .
        $this nltl:assessmentDate ?assessmentDate .
        FILTER (datatype(?constructionDate) = xsd:date)
        FILTER (datatype(?deliveryDate) = xsd:date)
        FILTER (datatype(?assessmentDate) = xsd:date)
        FILTER (?constructionDate < "2003-09-01"^^xsd:date)
        FILTER (
            YEAR(?assessmentDate) > YEAR(?deliveryDate) + 20
            ||
            (
                YEAR(?assessmentDate) = YEAR(?deliveryDate) + 20
                &&
                (
                    MONTH(?assessmentDate) > 1
                    ||
                    (
                        MONTH(?assessmentDate) = 1
                        &&
                        DAY(?assessmentDate) > 1
                    )
                )
            )
        )
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:ordinaryFrameScantlingsUsed true .
    FILTER NOT EXISTS {
        $this nltl:span ?spanQuantity .
        ?spanQuantity qudt:numericValue ?spanValue ;
                       qudt:unit unit:M .
        $this nltl:frameSpanWithinIceStrengtheningZone ?iceQuantity .
        ?iceQuantity qudt:numericValue ?iceValue ;
                      qudt:unit unit:M .
        FILTER(
            datatype(?spanValue) = xsd:decimal &&
            datatype(?iceValue) = xsd:decimal &&
            ?spanValue > 0 &&
            ?iceValue < (?spanValue * 0.15)
        )
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX sh: <http://www.w3.org/ns/shacl#>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT $this
WHERE {
    FILTER (
        NOT EXISTS {
            $this nltl:equivalentSupportStatusByDirectCalculation true
        }
    )
    {
        $this nltl:frameAsymmetrical true
    }
    UNION
    {
        $this nltl:frameWebAngleToShell ?angleNode .
        ?angleNode qudt:numericValue ?angle .
        ?angleNode qudt:unit unit:DEG .
        FILTER (?angle < 90)
    }
    FILTER NOT EXISTS {
        $this nltl:antitrippingSupportSpacing ?spacingNode .
        ?spacingNode qudt:numericValue ?spacing .
        ?spacingNode qudt:unit unit:MilliM .
        FILTER (?spacing <= 1300)
    }
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:shipBreadth ?breadthQuantity ;
          nltl:hasWeatherdeckHatch ?hatch .
    ?breadthQuantity qudt:numericValue ?breadthValue ;
                      qudt:unit <http://qudt.org/vocab/unit/M> .
    ?hatch nltl:hatchOpeningLength ?openingQuantity .
    ?openingQuantity qudt:numericValue ?openingValue ;
                      qudt:unit <http://qudt.org/vocab/unit/M> .

    FILTER (?openingValue > (?breadthValue / 2))

    FILTER (
        NOT EXISTS {
            ?hatch nltl:shipSideDeflection ?deflectionQuantity .
            ?deflectionQuantity qudt:numericValue ?deflectionValue ;
                                 qudt:unit <http://qudt.org/vocab/unit/M> .
        }
        ||
        NOT EXISTS {
            ?hatch nltl:hasHatchCoverDesignEvidence ?coverEvidence .
            ?coverEvidence rdf:type nltl:hatchCoverDesignEvidence .
        }
        ||
        NOT EXISTS {
            ?hatch nltl:hasHatchFittingDesignEvidence ?fittingEvidence .
            ?fittingEvidence rdf:type nltl:hatchFittingDesignEvidence .
        }
    )
}

PREFIX nltl: <https://w3id.org/nltl/vocab#>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX unit: <http://qudt.org/vocab/unit/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT $this
WHERE {
    $this nltl:propellerType ?type ;
          nltl:pitchValueKnown false .
    FILTER (?type = "CP"^^xsd:string)

    FILTER NOT EXISTS {
        $this nltl:propellerPitchAtMcrFreeRunning ?free ;
              nltl:propellerPitchAtMcrBollard ?bollard .
        ?free qudt:numericValue ?freeValue ;
              qudt:unit unit:M .
        ?bollard qudt:numericValue ?bollardValue ;
                 qudt:unit unit:M .
        FILTER (datatype(?freeValue) = xsd:decimal)
        FILTER (datatype(?bollardValue) = xsd:decimal)
        FILTER (
            ABS(?bollardValue - (0.7 * ?freeValue)) <=
            (0.000001 * ABS(0.7 * ?freeValue) + 0.000000001)
        )
    }
}
